import collections,json
def solve(a):
    H,W=len(a),len(a[0])
    cnt=collections.Counter(v for r in a for v in r)
    bg=max(cnt,key=cnt.get)
    fr=[v for v,n in cnt.most_common()[1:]][0]
    pts=[(r,c) for r in range(H) for c in range(W) if a[r][c]==fr]
    r0=min(r for r,c in pts); r1=max(r for r,c in pts); c0=min(c for r,c in pts); c1=max(c for r,c in pts)
    per={(r,c) for r in range(r0,r1+1) for c in range(c0,c1+1) if r in(r0,r1) or c in(c0,c1)}
    gaps={p for p in per if a[p[0]][p[1]]!=fr}
    print('gaps',sorted(gaps))
    out=[row[:] for row in a]
    dirs={}
    for (gr,gc) in gaps:
        # decide orientation
        if gr==r0: base=( -1,0)
        elif gr==r1: base=(1,0)
        else: base=(0,-1)
        dirs[(gr,gc)]=base+[(-1,-1),(1,-1)] if base[1]==0 else [(-1,1),(1,1)]
    for (gr,gc),dset in dirs.items():
        for dr,dc in dset+[base]:
            k=1
            while True:
                rr,cc=gr+dr*k,gc+dc*k
                if not(0<=rr<H and 0<=cc<W): break
                if a[rr][cc]!=fr: out[rr][cc]=4
                k+=1
    return out
